import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    N = int(next(iterator))
    B = int(next(iterator))

    skills = []
    for _ in range(N):
        row = []
        for j in range(N):
            row.append(int(next(iterator)))
        skills.append(row)

    bonuses = []
    for _ in range(B):
        k = int(next(iterator))
        p = int(next(iterator))
        a = int(next(iterator))
        bonuses.append((k, p, a))

    dp = [-1] * (1 << N)
    dp[0] = 0

    for mask in range(1 << N):
        if dp[mask] == -1:
            continue

        event_idx = bin(mask).count('1')
        if event_idx >= N:
            continue

        current_score = dp[mask]

        bonus_points = 0
        for k, p, a in bonuses:
            if event_idx >= k and current_score >= p:
                bonus_points += a

        new_base_score = current_score + bonus_points

        for cow in range(N):
            if not (mask & (1 << cow)):
                next_mask = mask | (1 << cow)
                skill_val = skills[cow][event_idx]
                total = new_base_score + skill_val

                if dp[next_mask] < total:
                    dp[next_mask] = total

    final_mask = (1 << N) - 1
    ans = dp[final_mask]

    bonus_points_final = 0
    for k, p, a in bonuses:
        if ans >= p:
            bonus_points_final += a

    print(ans + bonus_points_final)

if __name__ == "__main__":
    solve()

