The bug occurs because the `release` method adds the connection back to the pool but fails to update the `_in_use` counter. This causes the counter to keep increasing indefinitely, eventually hitting `max_size` and preventing new connections from being created or acquired, even though connections are sitting idle in the pool.

To fix this, you simply need to decrement `self._in_use` inside the `release` method before notifying waiting threads.

Here is the corrected code:

```python
import threading
from collections import deque

class ConnectionPool:
    def __init__(self, factory, max_size=5):
        self._factory = factory
        self._max_size = max_size
        self._pool = deque()
        self._in_use = 0
        self._lock = threading.Lock()
        self._available = threading.Condition(self._lock)

    def acquire(self, timeout=None):
        """Acquire a connection from the pool."""
        with self._available:
            while True:
                if self._pool:
                    conn = self._pool.popleft()
                    self._in_use += 1
                    return conn
                if self._in_use < self._max_size:
                    self._in_use += 1
                    return self._factory()
                # Pool exhausted, wait
                if not self._available.wait(timeout):
                    raise TimeoutError("Connection pool exhausted")

    def release(self, conn):
        """Return a connection to the pool."""
        with self._available:
            self._pool.append(conn)
            # FIX: Decrement _in_use here
            self._in_use -= 1
            self._available.notify()

    @property
    def available(self):
        with self._lock:
            return len(self._pool)

    @property
    def in_use(self):
        with self._lock:
            return self._in_use
